		&\Delta u_{2}=m_{g}^{2}\left(\mathrm{e}^{\frac{u_{1}}{N}+\frac{(N-1)}{N} u_{2}}-\mathrm{e}

\section{Gaussian states with noise and losses}
\label{appendix:gaussian states}
Consider a continuous-variable system of $d$ bosonic modes. Associated with each mode is a pair of creation and annihilation operators that satisfy the canonical commutation relations $[\hat{a}_j,\hat{a}_k^\dag] = \delta_{jk}$, $[\hat{a}_j,\hat{a}_k]=0$ and $[\hat{a}^\dag_j,\hat{a}^\dag_k]=0$. The corresponding quadrature operators for each mode are defined as
\begin{equation}
    \hat{q}_j = \frac{1}{\sqrt{2}}\left(\hat{a}_j^\dag + \hat{a}_j\right), \quad \hat{p}_j = \frac{i}{\sqrt{2}}\left(\hat{a}_j^\dag - \hat{a}_j\right),
\end{equation}
and fulfil the commutation relations $[\hat{q}_j,\hat{p}_k] = i\delta_{jk}$. By definition, a Gaussian state has a Wigner function of the form
\begin{equation}
\label{eqn:gaussian state}
W(z) = \frac{\sqrt{\det G}}{\pi^d}\ue^{-(z-Z)\cdot G(z-Z)},
\end{equation}
where $z = (q,p) \in \mathbb{R}^d \times \mathbb{R}^d$ are canonical phase-space coordinates, $Z$ is a vector of expectation values $Z_k = \langle \hat{z}_k\rangle$ with $\hat z = (\hat{q}_1,\ldots,\hat{q}_d,\hat{p}_1,\ldots,\hat{p}_d)$, and $G$ is a real, symmetric and positive definite matrix. A Gaussian state is therefore completely characterised by the first moments $Z$ and the covariances of the quadrature operators
\begin{equation}
\label{eqn:covariances}
(G^{-1})_{jk} = \langle \hat{z}_j \hat{z}_k + \hat{z}_k \hat{z}_j\rangle - 2\langle\hat{z}_j\rangle\langle\hat{z}_k\rangle.
\end{equation}
The matrix elements of a Gaussian state in the Fock basis can be expressed in terms of $Z$, $G$ and multi-dimensional Hermite polynomials \cite{Dodonov94}, where the latter can be generated recursively \cite{Kok01}.

The Gaussian states $\hat\rho$ in this work have first moments $Z$ equal to zero. For the remainder of this appendix we assume $Z=0$.

